 void Awake(){Application.logMessageReceived+=Log;StartCoroutine(Run());}void Log(string c,string s,LogType t){if(t==LogType.Exception)exceptions++;if(t==LogType.Assert)assertions++;if((t==LogType.Exception||t==LogType.Assert)&&!string.IsNullOrWhiteSpace(root)){Directory.CreateDirectory(root);File.AppendAllText(Path.Combine(root,"failure.txt"),t+": "+c+"\n"+s+"\n");}}
 IEnumerator Run(){group=Environment.GetEnvironmentVariable(Group);if(string.IsNullOrWhiteSpace(group))group=Environment.GetCommandLineArgs().FirstOrDefault(v=>v.StartsWith(GroupArgument,StringComparison.Ordinal))?[GroupArgument.Length..];if(string.IsNullOrWhiteSpace(group)&&File.Exists(RequestPath)){group=File.ReadAllText(RequestPath).Trim();File.Delete(RequestPath);}root=Path.Combine(Application.persistentDataPath,"u48-production-visual-captures",group);Directory.CreateDirectory(root);var progress=Path.Combine(root,"progress.txt");var failure=Path.Combine(root,"failure.txt");if(File.Exists(failure))File.Delete(failure);File.WriteAllText(progress,"request-consumed");catalog=U48ProductionVisualCatalog.LoadRequired();var entry=catalog.Resolve(group);File.AppendAllText(progress,"\ncatalog-resolved");yield return Wait(()=>FindAnyObjectByType<U1Stage1SceneBootstrap>()!=null,20,"bootstrap");bootstrap=FindAnyObjectByType<U1Stage1SceneBootstrap>();shell=FindAnyObjectByType<U46RuntimeShell>();gameplay=FindAnyObjectByType<Stage1GameplayRuntimeCoordinator>();battle=FindAnyObjectByType<U2BattleController>();player=FindAnyObjectByType<PlayerController>();levelUp=FindAnyObjectByType<U4LevelUpDemoController>();if(new object[]{shell,gameplay,battle,player,levelUp}.Any(v=>v==null))throw new InvalidOperationException("Production capture dependencies missing.");File.AppendAllText(progress,"\ndependencies-ready");var shots=Path.Combine(root,"screenshots");var results=Path.Combine(root,"results");Directory.CreateDirectory(shots);Directory.CreateDirectory(results);foreach(var f in Directory.GetFiles(shots))File.Delete(f);foreach(var f in Directory.GetFiles(results))File.Delete(f);shell.ReinitializeForVerification();File.AppendAllText(progress,"\nshell-reinitialized");yield return Prepare();File.AppendAllText(progress,"\nscenario-prepared");if(exceptions+assertions>0)throw new InvalidOperationException("Production capture runtime log failure.");foreach(var spec in Specs()){Viewport(spec.