 if(auxiliary!=null)Destroy(auxiliary);Destroy(bootstrap.gameObject);yield return null;var clean=FindAnyObjectByType<U48ProductionVisualBinder>()==null;File.WriteAllText(Path.Combine(root,"summary.json"),$"{{\n  \"schemaVersion\": 1,\n  \"assetGroup\": {Q(group)},\n  \"completedCaptureCount\": 3,\n  \"requiredStateCount\": {states.Distinct().Count()},\n  \"productionProvider\": true,\n  \"previewDependencyUsed\": false,\n  \"cleanupPassed\": {B(clean)},\n  \"exceptionCount\": {exceptions},\n  \"assertionFailureCount\": {assertions},\n  \"passed\": {B(clean&&exceptions==0&&assertions==0)}\n}}\n");Destroy(gameObject);}
 IEnumerator Prepare(){yield return new WaitForSecondsRealtime(.15f);if(group.StartsWith("stage-select-")){yield return Stage();yield break;}StartStage();yield return Wait(()=>shell.Flow.State==AppFlowState.Running,5,"running");battle.SetRuntimePaused(true);gameplay.SetRuntimePaused(false);if(group.StartsWith("hud-"))yield return Hud();else if(group.StartsWith("levelup-"))yield return Level();else if(group.StartsWith("replacement-"))yield return Replacement();else if(group.StartsWith("result-"))yield return Result();else yield return Gameplay();}
 IEnumerator Gameplay(){states.Add("production-owner-visible");var center=player.transform.position+new Vector3(.5f,.15f);if(group=="player-yui"){player.SetVerificationMoveInput(Vector2.right);states.Add("player-movement");}
