 else if(group=="stage1-background"){for(int i=0;i<10;i++)battle.SpawnEnemyForVerification(player.transform.position+new Vector3((i%5-2)*.55f,(i/5)*.5f));states.AddRange(new[]{"background-normal","normal-density","high-density"});}
 else if(group=="common-projectile"){battle.SpawnEnemyForVerification(center);battle.FireGameplayProjectile(1,1);states.Add("projectile");}
 else if(group=="hit-effect"){battle.SpawnEnemyForVerification(center);battle.NotifyPlayerDamageVisual();states.Add("hit");}
 else if(group=="enemy-death-effect"||group=="pickup-exp"||group=="movement-trail"){battle.SpawnEnemyForVerification(group=="movement-trail"?player.transform.position:center);battle.DamageEnemiesInRadius(group=="movement-trail"?player.transform.position:center,.3f,9999);states.Add(group=="enemy-death-effect"?"enemy-death":group=="pickup-exp"?"exp-pickup":"movement-trail");yield return new WaitForSecondsRealtime(.12f);}
 else if(group=="pickup-healing"){Aux(catalog.SpriteFor(group),center,.3f);states.Add("healing-pickup");}
 else if(group.StartsWith("ground-area-")){var id=group.EndsWith("black-ink-bottle")?"black_ink_bottle":group.EndsWith("streetlamp-ring")?"streetlamp_ring":"dawn_ink_lamp";if(id=="dawn_ink_lamp"){AcceptW("black_ink_bottle");AcceptW("streetlamp_ring");Max("black_ink_bottle");Max("streetlamp_ring");new EvolutionService(gameplay.Registry).TryApply(gameplay.Run.Inventory,"dawn_ink_lamp_fusion");}else AcceptW(id);gameplay.BeginGroundAreaVerification(id,center);battle.SpawnEnemyForVerification(center);states.AddRange(new[]{"spawn","active","tick","pre-despawn","post-despawn","enemy-inside","enemy-outside","player-overlap","high-density"});yield return new WaitForSecondsRealtime(.35f);}
 else if(group.StartsWith("kokuyou-")){var phase=group["kokuyou-".Length..];if(phase=="charging")gameplay.ApplyPlayerDamage(30);else{gameplay.ApplyPlayerDamage(100);if(phase is "active" or "recovery")gameplay.ActivateKokuyou();if(phase=="active")yield return Wait(()=>gameplay.Run.Kokuyou.Phase==KokuyouPhase.Active,2,"active");if(phase=="recovery")yield return Wait(()=>gameplay.Run.Kokuyou.Phase==KokuyouPhase.Recovery,12,"recovery");}states.AddRange(new[]{"normal","charging-early","charging-near-ready","ready","active-start","active-middle","active-high-density","recovery-start","recovery-middle","normal-restored",phase});}
 yield return new WaitForSecondsRealtime(.15f);}
 IEnumerator Hud(){gameplay.BeginVerificationScenario(RunGameplayScenarioOptions.SimulatorFullSlotReplacement(gameplay.Registry));AcceptW("black_ink_bottle");AcceptP("old_ticket");if(group.Contains("passive")){AcceptP("gold_compass");AcceptP("travel_badge");}if(group.Contains("rare"))gameplay.RareItems.Acquire(gameplay.Run,"dawn_ticket");if(group.Contains("hp"))gameplay.ApplyPlayerDamage(70);if(group.Contains("kokuyou"))gameplay.ApplyPlayerDamage(100);states.AddRange(new[]{"initial","partial-inventory","full-inventory","low-hp","rare","charging","ready","active","recovery","levelup-overlap"});yield return new WaitForSecondsRealtime(.15f);}
 IEnumerator Level(){levelUp.TriggerLevelUp();yield return new WaitForSecondsRealtime(.12f);var cards=FindObjectsByType<PaperCard>(FindObjectsInactive.Exclude).OrderBy(v=>v.CardIndex).ToArray();if(cards.Length!=3)throw new InvalidOperationException("three choices missing");cards[(Math.Abs(group.GetHashCode())%3)].OnPointerClick(null);states.AddRange(new[]{"open","three-choices","selected","non-selected","decline","longest-canonical-text"});yield return null;}
 IEnumerator Replacement(){gameplay.BeginVerificationScenario(RunGameplayScenarioOptions.SimulatorFullSlotReplacement(gameplay.Registry));AcceptW("black_ink_bottle");var offer=Choice(GameplayChoiceKind.Weapon,"streetlamp_ring");levelUp.ShowReplacementForVerification(offer);yield return new WaitForSecondsRealtime(.1f);var buttons=Slots();if(group.Contains("selected")||group.Contains("confirm")||group.Contains("owned")){buttons[1].Press();yield return null;}states.AddRange(new[]{"no-selection","confirm-disabled","selected-row","confirm-enabled","weapon-confirm","passive-confirm","cancel","reopen-reset"});}
 IEnumerator Result(){AcceptW("black_ink_bottle");AcceptP("old_ticket");if(group.Contains("inventory")){AcceptW("streetlamp_ring");AcceptP("gold_compass");}gameplay.RareItems.Acquire(gameplay.Run,"dawn_ticket");gameplay.Run.NotifyChanged();shell.CompleteVerificationRun(group.Contains("main"),true);yield return Wait(()=>shell.Flow.State==AppFlowState.Result,5,"result");if(group.Contains("retry"))Button("RetryButton").Select();else if(group.Contains("return"))Button("StageSelectButton").Select();states.AddRange(new[]{"normal-result","max-inventory","evolution","awakening","retry","return"});yield return new WaitForSecondsRealtime(.12f);}
