 void StartStage(){Button("StartStageButton").onClick.Invoke();}void AcceptW(string id){if(!gameplay.AcceptChoice(new LevelUpChoice{Kind=GameplayChoiceKind.Weapon,DefinitionId=id,NextLevel=1}))throw new InvalidOperationException("weapon "+id);}void AcceptP(string id){if(!gameplay.AcceptChoice(new LevelUpChoice{Kind=GameplayChoiceKind.Passive,DefinitionId=id,NextLevel=1}))throw new InvalidOperationException("passive "+id);}void Max(string id){var o=gameplay.Run.Inventory.Weapons.Find(v=>v.Id==id);while(o.Level<gameplay.Registry.GetWeapon(id).MaxLevel)gameplay.AcceptChoice(new LevelUpChoice{Kind=GameplayChoiceKind.Weapon,DefinitionId=id,NextLevel=o.Level+1});}LevelUpChoice Choice(GameplayChoiceKind k,string id)=>gameplay.CandidateService.CreateChoices(gameplay.Run,new SeededRandomSource(48),100).First(v=>v.Kind==k&&v.DefinitionId==id);static PaperButton[] Slots()=>FindObjectsByType<PaperButton>(FindObjectsInactive.Exclude).Where(v=>v.name.StartsWith("ReplacementSlotButton_")).OrderBy(v=>v.name).ToArray();static Button Button(string n)=>FindObjectsByType<Button>(FindObjectsInactive.Include).First(v=>v.name==n);void Aux(Sprite s,Vector3 p,float size){auxiliary=new GameObject("U48ProductionHealing",typeof(SpriteRenderer));var r=auxiliary.GetComponent<SpriteRenderer>();r.sprite=s;r.sortingOrder=30;auxiliary.transform.position=p;auxiliary.transform.localScale=Vector3.one*size/Mathf.Max(.001f,Mathf.Max(s.bounds.size.x,s.bounds.size.y));}
 static IEnumerable<(string name,int w,int h)>Specs(){yield return("compact",360,800);yield return("standard",390,844);yield return("large",430,932);}static void Viewport(int w,int h){Screen.SetResolution(w,h,false);foreach(var s in FindObjectsByType<CanvasScaler>(FindObjectsInactive.Include))s.referenceResolution=new Vector2(w,h);}static IEnumerator Capture(string p,int w,int h){var s=new Texture2D(Screen.width,Screen.height,TextureFormat.RGBA32,false);s.ReadPixels(new Rect(0,0,Screen.width,Screen.height),0,0);s.Apply();var rt=RenderTexture.GetTemporary(w,h);Graphics.Blit(s,rt);var old=RenderTexture.active;RenderTexture.active=rt;var o=new Texture2D(w,h,TextureFormat.RGBA32,false);o.ReadPixels(new Rect(0,0,w,h),0,0);o.Apply();RenderTexture.active=old;RenderTexture.ReleaseTemporary(rt);Destroy(s);var px=o.GetPixels32();var rgb=new byte[w*h*3];int z=0;for(int y=h-1;y>=0;y--)for(int x=0;x<w;x++){var c=px[y*w+x];rgb[z++]=c.r;rgb[z++]=c.g;rgb[z++]=c.b;}using(var f=File.Create(p)){var hd=Encoding.ASCII.GetBytes($"P6\n{w} {h}\n255\n");f.Write(hd);f.Write(rgb);}Destroy(o);yield return null;}IEnumerator Wait(Func<bool>f,float t,string l){var s=Time.realtimeSinceStartup;while(!f()&&Time.realtimeSinceStartup-s<t)yield return null;if(!f())throw new TimeoutException(l);}void OnDestroy(){Application.logMessageReceived-=Log;StopAllCoroutines();}static string Q(string v)=>"\""+v.Replace("\\","\\\\").Replace("\"","\\\"")+"\"";static string B(bool v)=>v?"true":"false";static string A(IEnumerable<string>v)=>"["+string.Join(",",v.Select(Q))+"]";
